&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;font-family: tahoma, arial, helvetica, sans-serif;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;About the Role:&lt;/span&gt;&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;br&gt;&lt;span style=&quot;font-family: tahoma, arial, helvetica, sans-serif;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;We are looking for a highly motivated&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;Sales Engineer&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt; with a strong background in AI infrastructure to join our dynamic team. In this role, you will play a critical part in driving enterprise sales, supporting both pre-sales and post-sales activities, and partnering closely with account executives to deliver cutting-edge solutions to our clients.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span style=&quot;font-family: tahoma, arial, helvetica, sans-serif;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Key Responsibilities:&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li style=&quot;font-family: tahoma, arial, helvetica, sans-serif;&quot; data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;2&quot; data-list-defn-props=&quot;{&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;1&quot; data-aria-level=&quot;1&quot;&gt;&lt;span style=&quot;font-family: tahoma, arial, helvetica, sans-serif;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Leverage &lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;10+ years of experience&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt; as a Sales Engineer to drive technical sales processes and customer success.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
